// g_Stage_Terrain size: 2560 Bytes


void g_Stage_DrawRow(const u8* layer, u8 row, UY atlasY, UY destY)
{
	const u8* src = layer + ((u16)row * G_STAGE_W);
	u16 dx = 0;
	u8 col = G_STAGE_W;
	while(col--)
	{
		u8 cell = *src++;
		VDP_CommandHMMM((u16)(cell % G_STAGE_ATLAS_COLS) * G_STAGE_CELL_W,
		                atlasY + ((cell / G_STAGE_ATLAS_COLS) * G_STAGE_CELL_H),
		                dx, destY, G_STAGE_CELL_W, G_STAGE_CELL_H);
		dx += G_STAGE_CELL_W;
	}
}
